components.css:
.ds-title-block { border: 1px solid var(--deep, #16307E); border-radius: 8px; overflow: hidden; background: var(--deep, #16307E); }
.ds-tb-grid { display: grid; grid-template-columns: repeat(9, minmax(0, 1fr)); }
.ds-tb-cell { padding: .6rem .75rem .62rem; border-right: 1px solid var(--deep-rule, #2B4794); border-bottom: 1px solid var(--deep-rule, #2B4794); min-width: 0; }
.ds-tb-cell:last-child { border-right: none; }
.ds-tb-key { display: block; font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: .625rem; font-weight: 500; letter-spacing: .11em; text-transform: uppercase; color: var(--deep-mute, #A9BCEE); margin-bottom: .2rem; }
.ds-tb-val { display: block; font-size: 1.02rem; font-weight: 600; color: var(--deep-ink, #FFFFFF); font-variant-numeric: tabular-nums; letter-spacing: -.015em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ds-tb-val.sm { font-size: .8rem; }
.ds-tb-strip { display: flex; flex-wrap: wrap; gap: 0 1.5rem; padding: .5rem .75rem; border-top: 1px solid var(--deep-rule, #2B4794); background: var(--deep-soft, #0F2358); }
.ds-tb-strip span { font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: .625rem; letter-spacing: .1em; text-transform: uppercase; color: var(--deep-mute, #A9BCEE); }
.ds-tb-strip b { color: var(--deep-ink, #FFFFFF); font-weight: 600; margin-left: .34rem; font-variant-numeric: tabular-nums; }
.ds-dark .ds-title-block { background: #3E5AD2; border-color: #3E5AD2; }
.ds-dark .ds-tb-cell { border-color: #5A78DE; }
.ds-dark .ds-tb-key, .ds-dark .ds-tb-strip span { color: #DCE6FF; }
.ds-dark .ds-tb-val, .ds-dark .ds-tb-strip b { color: #FFFFFF; }
.ds-dark .ds-tb-strip { background: #1E2E66; border-color: #5A78DE; }

.ds-btn-primary { display: inline-flex; align-items: center; gap: .45rem; border: 1px solid var(--deep, #16307E); border-radius: 6px; background: var(--deep, #16307E); color: var(--deep-ink, #FFFFFF); font-family: 'Archivo', 'Segoe UI', system-ui, sans-serif; font-size: .84rem; font-weight: 600; letter-spacing: -.005em; padding: .5rem 1rem; cursor: pointer; transition: background .12s ease, border-color .12s ease; }
.ds-btn-primary:hover { background: var(--deep-hi, #24439B); border-color: var(--deep-hi, #24439B); }
.ds-btn-primary:focus-visible { outline: 2px solid var(--accent, #1F4FD8); outline-offset: 2px; }
.ds-btn-primary:active { background: var(--deep-hi, #24439B); }
.ds-btn-primary:disabled { opacity: .45; cursor: not-allowed; }
.ds-dark .ds-btn-primary { background: #3E5AD2; border-color: #3E5AD2; color: #FFFFFF; }
.ds-dark .ds-btn-primary:hover { background: #4C6BE0; border-color: #4C6BE0; }

.ds-btn-secondary { display: inline-flex; align-items: center; gap: .45rem; border: 1px solid var(--rule, #C9C4B8); border-radius: 6px; background: var(--sheet, #FFFFFF); color: var(--ink, #16181A); font-family: 'Archivo', 'Segoe UI', system-ui, sans-serif; font-size: .84rem; font-weight: 600; letter-spacing: -.005em; padding: .5rem 1rem; cursor: pointer; transition: background .12s ease, border-color .12s ease; }
.ds-btn-secondary:hover { background: var(--paper, #F7F6F2); border-color: var(--ink2, #3C3F45); }
.ds-btn-secondary:focus-visible { outline: 2px solid var(--accent, #1F4FD8); outline-offset: 2px; }
.ds-btn-secondary:active { background: var(--paper, #F7F6F2); }
.ds-dark .ds-btn-secondary { background: #1B1E23; border-color: #33373E; color: #E9E7E2; }
.ds-dark .ds-btn-secondary:hover { background: #14161A; border-color: #C6C4BE; }

.ds-chip { display: inline-block; font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: .66rem; font-weight: 600; letter-spacing: .1em; text-transform: uppercase; padding: .28rem .5rem; border-radius: 4px; }
.ds-chip-low { background: var(--band-low-bg, #DCE5FA); color: var(--band-low-fg, #1B2C57); }
.ds-chip-mid { background: var(--band-mid-bg, #9DB6F2); color: var(--band-mid-fg, #15264D); }
.ds-chip-high { background: var(--band-high-bg, #96590C); color: var(--band-high-fg, #FFFFFF); }
.ds-dark .ds-chip-low { background: #1E2740; color: #C9D6F8; }
.ds-dark .ds-chip-mid { background: #3E5AB5; color: #EAF0FF; }
.ds-dark .ds-chip-high { background: #E3A94A; color: #1A1206; }

.ds-scale { border: 1px solid var(--rule, #C9C4B8); border-radius: 8px; background: var(--sheet, #FFFFFF); padding: .85rem 1rem .7rem; }
.ds-scale-head { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 1.7rem; gap: 1rem; }
.ds-scale-title { font-family: 'Archivo', 'Segoe UI', system-ui, sans-serif; font-size: .78rem; font-weight: 600; color: var(--ink, #16181A); }
.ds-scale-note { font-family: 'Archivo', 'Segoe UI', system-ui, sans-serif; font-size: .72rem; color: var(--muted, #6B6A64); }
.ds-scale-track { position: relative; height: 26px; border: 1px solid var(--rule, #C9C4B8); border-radius: 4px; display: flex; overflow: visible; }
.ds-seg { height: 100%; display: flex; align-items: center; padding-left: .55rem; }
.ds-seg span { font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: .58rem; letter-spacing: .11em; text-transform: uppercase; }
.ds-seg-low { background: var(--band-low-bg, #DCE5FA); color: var(--band-low-fg, #1B2C57); flex: none; }
.ds-seg-mid { background: var(--band-mid-bg, #9DB6F2); color: var(--band-mid-fg, #15264D); flex: none; }
.ds-seg-high { background: var(--band-high-bg, #96590C); color: var(--band-high-fg, #FFFFFF); flex: 1; }
.ds-marker { position: absolute; top: -6px; bottom: -6px; width: 2px; background: var(--ink, #16181A); transform: translateX(-1px); animation: ds-marker-in .5s cubic-bezier(.16,.84,.44,1) both; }
.ds-marker::after { content: ''; position: absolute; top: -4px; left: -3px; width: 8px; height: 8px; background: var(--ink, #16181A); border-radius: 50%; }
.ds-marker-val { position: absolute; top: -1.5rem; left: 50%; transform: translateX(-50%); font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: .68rem; font-weight: 600; color: var(--ink, #16181A); white-space: nowrap; background: var(--sheet, #FFFFFF); border: 1px solid var(--rule, #C9C4B8); border-radius: 3px; padding: .1rem .32rem; animation: ds-chip-in .5s .08s cubic-bezier(.16,.84,.44,1) both; }
.ds-ticks { position: relative; height: 1rem; margin-top: .3rem; }
.ds-tick { position: absolute; transform: translateX(-50%); font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: .58rem; letter-spacing: .08em; color: var(--muted, #6B6A64); white-space: nowrap; }
.ds-tick.hard { color: var(--ink2, #3C3F45); font-weight: 600; }
@keyframes ds-marker-in { from { opacity: 0; transform: translateX(-1px) scaleY(.35); } to { opacity: 1; transform: translateX(-1px) scaleY(1); } }
@keyframes ds-chip-in { from { opacity: 0; transform: translateX(-50%) translateY(5px); } to { opacity: 1; transform: translateX(-50%) translateY(0); } }
.ds-dark .ds-scale { background: #1B1E23; border-color: #33373E; }
.ds-dark .ds-seg-low { background: #1E2740; color: #C9D6F8; }
.ds-dark .ds-seg-mid { background: #3E5AB5; color: #EAF0FF; }
.ds-dark .ds-seg-high { background: #E3A94A; color: #1A1206; }
.ds-dark .ds-marker-val { background: #1B1E23; border-color: #33373E; color: #E9E7E2; }

.ds-cm { display: grid; grid-template-columns: 1fr 1fr; border: 1px solid var(--rule, #C9C4B8); border-radius: 8px; overflow: hidden; background: var(--sheet, #FFFFFF); }
.ds-cm-cell { padding: .6rem .85rem .7rem; border-right: 1px solid var(--rule-soft, #E3E0D8); border-bottom: 1px solid var(--rule-soft, #E3E0D8); }
.ds-cm-cell:nth-child(2n) { border-right: none; }
.ds-cm-cell:nth-child(n+3) { border-bottom: none; }
.ds-cm-cell.hit { background: var(--accent-soft, #E4EAFB); }
.ds-cm-key { display: block; font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: .6rem; font-weight: 500; letter-spacing: .12em; text-transform: uppercase; color: var(--muted, #6B6A64); margin-bottom: .22rem; }
.ds-cm-val { display: block; font-size: 1.55rem; font-weight: 650; letter-spacing: -.025em; color: var(--ink, #16181A); font-variant-numeric: tabular-nums; line-height: 1.15; }
.ds-cm-desc { display: block; font-size: .76rem; color: var(--muted, #6B6A64); margin-top: .12rem; }
.ds-dark .ds-cm { background: #1B1E23; border-color: #33373E; }
.ds-dark .ds-cm-cell { border-color: #262A30; }
.ds-dark .ds-cm-cell.hit { background: #1E2740; }

.ds-tabs { display: flex; gap: .35rem; border-bottom: 1px solid var(--rule, #C9C4B8); }
.ds-tab { display: flex; align-items: center; gap: .45rem; margin-right: 1.35rem; padding: .5rem 0 .55rem; font-family: 'Archivo', 'Segoe UI', system-ui, sans-serif; font-size: .82rem; font-weight: 600; letter-spacing: -.01em; color: var(--muted, #6B6A64); cursor: pointer; transition: color .12s ease; }
.ds-tab:hover { color: var(--deep-hi, #24439B); }
.ds-tab:focus-visible { outline: 2px solid var(--accent, #1F4FD8); outline-offset: 2px; }
.ds-tab.active { color: var(--deep, #16307E); border-bottom: 2px solid var(--deep, #16307E); margin-bottom: -1px; }
.ds-tab-ico { width: 15px; height: 15px; border: 1.5px solid currentColor; border-radius: 3px; }
.ds-dark .ds-tab { color: #8E8C86; }
.ds-dark .ds-tab:hover { color: #4C6BE0; }
.ds-dark .ds-tab.active { color: #C9D8FF; border-bottom-color: #C9D8FF; }

.ds-field { display: block; }
.ds-field-label { display: block; font-family: 'Archivo', 'Segoe UI', system-ui, sans-serif; font-size: .74rem; font-weight: 500; letter-spacing: .005em; color: var(--muted, #6B6A64); margin-bottom: .18rem; }
.ds-field-control { display: flex; align-items: center; justify-content: space-between; gap: .5rem; border: 1px solid var(--rule, #C9C4B8); border-radius: 6px; background: var(--sheet, #FFFFFF); color: var(--ink, #16181A); font-family: 'Archivo', 'Segoe UI', system-ui, sans-serif; font-size: .85rem; padding: .4rem .75rem; }
.ds-field:focus-within .ds-field-control { border-color: var(--accent, #1F4FD8); box-shadow: 0 0 0 2px var(--accent-soft, #E4EAFB); }
.ds-dark .ds-field-label { color: #8E8C86; }
.ds-dark .ds-field-control { background: #1B1E23; border-color: #33373E; color: #E9E7E2; }
